/**
 * Shared handler for OpenAI-compatible chat/completions API.
 * Works with: OpenAI, Qwen (dashscope compat mode), Kimi (Moonshot).
 */
async function generateWithOpenaiCompat(url, apiKey, model, system, prompt) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 30_000);
    try {
        const response = await fetch(url, {
            method: 'POST',
            headers: {
                'content-type': 'application/json',
                authorization: `Bearer ${apiKey}`,
            },
            body: JSON.stringify({
                model,
                messages: [
                    { role: 'system', content: system },
                    { role: 'user', content: prompt },
                ],
                max_tokens: 600,
            }),
            signal: controller.signal,
        });
        if (!response.ok) {
            const status = response.status;
            throw new Error(`OpenAI-compat request failed with status ${status}`);
        }
        const data = (await response.json());
        const text = data.choices?.[0]?.message?.content?.trim();
        if (!text)
            throw new Error('OpenAI-compat returned empty content');
        return text;
    }
    finally {
        clearTimeout(timeout);
    }
}

